<?php foreach(array_slice($preview['issues'],0,100)as$r):?><p><a href="<?=ADMIN?>/catalog-properties/edit?id=<?=$r['product_id']?>">#<?=$r['product_id']?></a> — <?=$e($r['reason'])?></p><?php endforeach ?><small>Показано до 100 отличий и 100 замечаний.</small></div></div>
<?php else:?><div class="card"><div class="card-body"><h2 class="h5">Сохранённые связи</h2><?php if(!$bindings):?><p>Связей пока нет. Каталог использует прежние фильтры.</p><?php endif ?><?php foreach($bindings as$id=>$b):?><p><a href="<?=ADMIN?>/catalog-facet-bindings?group=<?=$id?>">Группа #<?=$id?></a> · <?=$e($b['property_code'])?> · <?=$e($modes[$b['mode']])?></p><?php endforeach ?></div></div><?php endif ?>
